window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[146]={"id":"146","numero":146,"titre":"Vaccinations","objectifs":[{"id":"146-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition (vaccin et sérothérapie), les différents types de vaccins, les principaux objectifs de la vaccination, de primovaccination, rappel et rattrapage","contenu":"<p>La <span class=\"kw-def\">vaccination</span> est une <strong>immunoprophylaxie active</strong> : administration d'une préparation antigénique ou d'une forme atténuée du pathogène, induisant une réponse <span class=\"kw-bio\">cellulaire et/ou humorale</span>. La réponse est <strong>retardée mais durable</strong>. La <span class=\"kw-def\">sérothérapie</span> est une <strong>immunoprophylaxie passive</strong> (humorale) : administration d'<span class=\"kw-bio\">immunoglobulines</span>, conférant une protection <strong>immédiate mais transitoire</strong> — le système immunitaire du sujet n'est pas mis en jeu.</p>\n      <h4 style=\"margin:16px 0 6px;font-size:14.5px;font-weight:700;\">Objectifs et notions clés</h4>\n      <table >\n        <thead><tr><th>Notion</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Primovaccination</span></td><td>Premières injections, déclenchant la <span class=\"kw-def\">réponse primaire</span></td></tr>\n          <tr><td><span class=\"kw-def\">Rappel</span></td><td>Injection ultérieure qui renforce et maintient l'immunité (<span class=\"kw-def\">réponse secondaire</span>)</td></tr>\n          <tr><td><span class=\"kw-def\">Rattrapage</span></td><td>Stratégie visant à compléter un calendrier non respecté ou un statut vaccinal inconnu</td></tr>\n          <tr><td>Objectif global</td><td>Protection <strong>individuelle et collective</strong> (immunité de groupe) contre <span class=\"kw-clinique\">les</span> maladies infectieuses</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:16px 0 6px;font-size:14.5px;font-weight:700;\"><span class=\"kw-clinique\">Les</span> deux grands types de vaccins</h4>\n      <table >\n        <thead><tr><th>Critère</th><th>Vaccins vivants atténués</th><th>Vaccins inertes</th></tr></thead>\n        <tbody>\n          <tr><td>Définition</td><td>Agents <span class=\"kw-etio\">infectieux</span> <span class=\"kw-def\">vivants à virulence atténuée</span></td><td>Agents <span class=\"kw-def\">inactivés / tués</span> (traitement physique ou chimique) ; ou <span class=\"kw-def\">sous-unitaires</span> (protéines, polysaccharides, recombinants)</td></tr>\n          <tr><td>Avantages</td><td>Protection rapide (<span class=\"kw-chiffre\">2 semaines</span>), prolongée et mixte ; rappel souvent non nécessaire (<span class=\"kw-chiffre\">1-2 doses</span>)</td><td><span class=\"kw-def\">Aucun pouvoir infectant</span> — aucun risque de maladie infectieuse vaccinale</td></tr>\n          <tr><td>Inconvénients · CI</td><td><span class=\"kw-ci\">Immunodépression</span> ; <span class=\"kw-ci\">grossesse</span> ; <span class=\"kw-ci\">Ig &lt; 3 mois</span> (sauf anti-Rhésus) ; <span class=\"kw-alerte\">risque de maladie infectieuse vaccinale</span></td><td>Immunogénicité plus faible → <span class=\"kw-def\">adjuvant</span> souvent nécessaire ; réponse surtout humorale (sauf Hib, <span class=\"kw-ttt\">hépatite B</span>, coqueluche) ; plusieurs doses espacées de <span class=\"kw-chiffre\">≥ 1 mois</span></td></tr>\n          <tr><td>Cibles virales</td><td><span class=\"kw-ttt\">ROR</span> ; <span class=\"kw-ttt\">fièvre jaune</span> ; <span class=\"kw-ttt\">varicelle</span> ; <span class=\"kw-ttt\">zona</span> ; <span class=\"kw-ttt\">rotavirus</span> (per os) ; <span class=\"kw-ttt\">dengue</span> ; <span class=\"kw-ttt\">grippe nasale</span></td><td><span class=\"kw-ttt\">Grippe injectable</span> ; <span class=\"kw-ttt\">poliomyélite</span> ; <span class=\"kw-ttt\">hépatite A</span> ; <span class=\"kw-ttt\">rage</span> ; encéphalites (virus entiers) ; <span class=\"kw-ttt\">hépatite B</span> et <span class=\"kw-ttt\">HPV</span> (recombinants) ; <span class=\"kw-ttt\">SARS-CoV-2</span> (acides nucléiques ou vecteur <span class=\"kw-etio\">viral</span>)</td></tr>\n          <tr><td>Cibles bactériennes</td><td><span class=\"kw-ttt\">BCG</span> (voie intradermique)</td><td><span class=\"kw-ttt\">Diphtérie-tétanos</span> (anatoxines) ; <span class=\"kw-ttt\">coqueluche acellulaire</span> et <span class=\"kw-ttt\">méningocoque B</span> (protéines) ; <span class=\"kw-ttt\">pneumocoque 23</span> (polyoside non conjugué) ; <span class=\"kw-ttt\">pneumocoque 13</span>, <span class=\"kw-ttt\">méningocoque C</span>, <span class=\"kw-ttt\">méningocoque ACYW</span>, <span class=\"kw-ttt\">Hib</span> (polyosides conjugués)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Mnémo cibles des vaccins vivants — BRAVO DG :</strong> BCG, <span class=\"kw-etio\">Rotavirus</span>, Amaril (<span class=\"kw-clinique\">fièvre</span> jaune), <span class=\"kw-etio\">VZV</span> (varicelle), Oreillons, Dengue, Grippe nez.</div>\n      <div class=\"callout callout-info\"><strong>À noter :</strong> <span class=\"kw-clinique\">les</span> vaccins anti-parasitaires et anti-fongiques relèvent encore du domaine de la recherche.</div>","frequence":0},{"id":"146-2","rang":"A","rubrique":"Physiopathologie","titre":"Connaître les principes de la protection vaccinale","contenu":"<p>La <span class=\"kw-def\">réponse primaire</span> (lors de la primovaccination) se traduit par une ascension différée et lente des anticorps <span class=\"kw-bio\">IgM</span> en <span class=\"kw-chiffre\">10-15 jours</span>, suivie d'une décroissance rapide. La <span class=\"kw-def\">réponse secondaire</span> (injection rapprochée, <span class=\"kw-chiffre\">1-2 mois</span> plus tard) est rapide, importante et durable, avec production d'<span class=\"kw-bio\">IgG</span> d'affinité augmentée : c'est la <strong>mémoire immunologique</strong>.</p>\n      <div class=\"callout callout-info\"><strong>Rappels naturels :</strong> tant qu'un agent <span class=\"kw-etio\">infectieux</span> continue de circuler, <span class=\"kw-clinique\">les</span> contacts itératifs entretiennent l'immunité — ex. <span class=\"kw-ttt\">Hib</span> : pas de <span class=\"kw-ttt\">rappel vaccinal</span> tardif nécessaire après <span class=\"kw-chiffre\">5 ans</span>. Quand la circulation se réduit (ex. <span class=\"kw-ttt\">coqueluche</span>), ces rappels naturels deviennent aléatoires → des rappels vaccinaux tardifs deviennent nécessaires.</div>\n      <h4 style=\"margin:16px 0 6px;font-size:14.5px;font-weight:700;\">Antigènes protéiques <span class=\"kw-bio\">vs</span> polyosidiques</h4>\n      <table >\n        <thead><tr><th>Type d'<span class=\"kw-bio\">antigène</span></th><th>Caractéristiques de la réponse</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Antigènes protéiques</span> (thymo-dépendants)</td><td>Réponse primaire faible (<span class=\"kw-bio\">IgM</span>) puis fort <strong>effet rappel</strong> (<span class=\"kw-bio\">IgG</span>) grâce à un pool de cellules mémoire</td></tr>\n          <tr><td><span class=\"kw-def\">Antigènes polyosidiques</span> (thymo-indépendants)</td><td>Réponse faible et lente, <span class=\"kw-alerte\">sans cellules mémoire ni effet rappel</span> ; médiocre avant <span class=\"kw-chiffre\">2 ans</span> → corrigée par la <span class=\"kw-def\">conjugaison</span> à une protéine (immunogène dès <span class=\"kw-chiffre\">6 semaines</span>, effet mémoire, élimination du portage)</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:16px 0 6px;font-size:14.5px;font-weight:700;\">Facteurs d'immunogénicité</h4>\n      <table >\n        <thead><tr><th>Facteur</th><th>Effet sur la réponse vaccinale</th></tr></thead>\n        <tbody>\n          <tr><td>Type de vaccin</td><td>Vivants &gt; inertes ; protéiques &gt; polyosidiques ; conjugués &gt; non-conjugués</td></tr>\n          <tr><td><span class=\"kw-def\">Adjuvants</span></td><td>Dérivés de l'<span class=\"kw-bio\">aluminium</span> (majoritaires), émulsions huile/eau, dérivés du <span class=\"kw-bio\">LPS</span> <span class=\"kw-etio\">bactérien</span> ; innocuité largement établie</td></tr>\n          <tr><td>Âge</td><td><span class=\"kw-clinique\">Nouveau-né</span> : système immunitaire immature + AC maternels neutralisants → peu ou pas de vaccin ; jeune enfant et adulte jeune : très bonne réponse ; décroissance dès <span class=\"kw-chiffre\">50 ans</span> (<span class=\"kw-def\">immunosénescence</span>)</td></tr>\n          <tr><td><span class=\"kw-ci\">Immunodépression</span></td><td>Réponse vaccinale fréquemment diminuée + <span class=\"kw-ci\">contre-indication</span> aux vaccins vivants</td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"146-3","rang":"A","rubrique":"Prise en charge","titre":"Vacciner en pratique courante, adulte et enfants : modalités pratiques d'administration des vaccins (voie d'administration, nombre simultané de doses) ; effets indésirables ; rapport bénéfice/risque ; contre-indications ; informations aux parents ; les principaux acteurs pratiquant la vaccination","contenu":"<p><strong>Acteurs de la <span class=\"kw-ttt\">vaccination</span> :</strong> la <strong>prescription</strong> revient au médecin et à la sage-femme (pour certaines vaccinations) ; l'<strong>administration</strong> au médecin, à la sage-femme et à l'infirmier (+ le <span class=\"kw-ttt\">pharmacien</span> pour la <span class=\"kw-etio\">grippe</span> saisonnière). <span class=\"kw-clinique\">Les</span> services départementaux de <span class=\"kw-def\">PMI</span> assurent les vaccinations de l'enfant jusqu'à <span class=\"kw-chiffre\">6 ans</span>.</p>\n      <h4 style=\"margin:16px 0 6px;font-size:14.5px;font-weight:700;\">Modalités d'administration</h4>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Règle</th></tr></thead>\n        <tbody>\n          <tr><td>Nombre simultané</td><td><strong>Jusqu'à 4 vaccins</strong> le même jour, en sites différents séparés de <span class=\"kw-chiffre\">≥ 2,5 cm</span></td></tr>\n          <tr><td>Intervalle</td><td>N'importe quel intervalle, <span class=\"kw-alerte\">sauf ≥ 1 mois entre 2 vaccins viraux vivants atténués non combinés</span></td></tr>\n          <tr><td>Conservation</td><td><span class=\"kw-chiffre\">2-8 °C</span> — dans le réfrigérateur, jamais dans la porte</td></tr>\n          <tr><td><span class=\"kw-def\">Surveillance</span></td><td><span class=\"kw-chiffre\">20 min</span> en salle d'attente, pour détecter une réaction anaphylactique</td></tr>\n          <tr><td>Traçabilité et PEC</td><td>Attestation écrite (carnet) ; remboursement à <span class=\"kw-chiffre\">65 %</span> par l'Assurance maladie</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:16px 0 6px;font-size:14.5px;font-weight:700;\">Voies d'administration</h4>\n      <table >\n        <thead><tr><th>Voie</th><th>Indication et site</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">IM</span></td><td>Majorité des vaccins ; <span class=\"kw-chiffre\">&lt; 2 ans</span> face antérolatérale de la cuisse, <span class=\"kw-chiffre\">&gt; 2 ans</span> deltoïde (possible dès <span class=\"kw-chiffre\">&gt; 1 an</span>, <span class=\"kw-chiffre\">&gt; 10 kg</span> ou marche <span class=\"kw-etio\">acquise</span>) ; <span class=\"kw-alerte\">jamais au niveau de la fesse</span></td></tr>\n          <tr><td><span class=\"kw-def\">SC</span></td><td>Préférée en cas de troubles sévères de l'hémostase (compression <span class=\"kw-chiffre\">5 min</span>) ; site : <span class=\"kw-chiffre\">&lt; 1 an</span> face antérolatérale de la cuisse, <span class=\"kw-chiffre\">&gt; 1 an</span> face postérieure du bras</td></tr>\n          <tr><td><span class=\"kw-def\">Intradermique</span></td><td>Réservée au <span class=\"kw-ttt\">BCG</span> (forte densité de cellules dendritiques du derme)</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:16px 0 6px;font-size:14.5px;font-weight:700;\"><span class=\"kw-ci\">Contre-indications</span></h4>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Contre-indications</th></tr></thead>\n        <tbody>\n          <tr><td>Communes</td><td><span class=\"kw-ci\">Hypersensibilité</span> lors d'une <span class=\"kw-ttt\">vaccination</span> antérieure ; <span class=\"kw-ci\">syndrome de Guillain-Barré &lt; 6 semaines</span> après un vaccin ; infection aiguë grave (différer la vaccination)</td></tr>\n          <tr><td>Vaccins vivants</td><td><span class=\"kw-ci\">Immunodépression</span> ; <span class=\"kw-ci\">grossesse</span> ; <span class=\"kw-ci\">Ig &lt; 3 mois</span> (sauf anti-Rhésus) — contraception <span class=\"kw-chiffre\">1 mois</span> après l'injection</td></tr>\n          <tr><td><span class=\"kw-clinique\">Fièvre</span> jaune et <span class=\"kw-etio\">grippe</span></td><td><span class=\"kw-ci\">Allergie avérée à l'œuf</span></td></tr>\n          <tr><td>Coqueluche</td><td><span class=\"kw-ci\">Encéphalopathie inexpliquée &lt; 7 j</span> après un vaccin ; épilepsie non contrôlée</td></tr>\n          <tr><td>Anatoxines et polyosides</td><td>Aucune <span class=\"kw-ci\">contre-indication</span> spécifique</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:16px 0 6px;font-size:14.5px;font-weight:700;\">Effets indésirables</h4>\n      <table >\n        <thead><tr><th>Type</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr><td>Bénins</td><td>Locaux : <span class=\"kw-clinique\">douleur</span>, <span class=\"kw-clinique\">érythème</span>, <span class=\"kw-clinique\">induration</span> ; généraux : <span class=\"kw-clinique\">fièvre</span> et <span class=\"kw-clinique\">asthénie</span> chez le nourrisson, <span class=\"kw-clinique\">céphalées</span> et <span class=\"kw-clinique\">arthromyalgies</span> chez l'adulte ; précoces &lt;<span class=\"kw-chiffre\"> 48-72 h</span> pour <span class=\"kw-clinique\">les</span> inertes, retardés pour les vivants</td></tr>\n          <tr><td>Graves</td><td><span class=\"kw-alerte\">Réaction anaphylactique</span> ; phénomènes dysimmunitaires ; maladies infectieuses vaccinales chez l'immunodéprimé</td></tr>\n          <tr><td>Spécifiques</td><td><span class=\"kw-ttt\">DTCaP-Hib</span> : <span class=\"kw-clinique\">hypotonie-hyporéactivité</span>, cris persistants ; <span class=\"kw-ttt\">ROR</span> : <span class=\"kw-clinique\">fièvre et éruption J5-12</span>, arthralgies, <span class=\"kw-alerte\">convulsions</span> fébriles, thrombopénie ; <span class=\"kw-ttt\">BCG</span> : <span class=\"kw-clinique\">ulcération et adénopathie 3-5 mois</span>, BCGite si immunodéprimé ; <span class=\"kw-ttt\">coqueluche</span> : <span class=\"kw-alerte\">convulsions</span> fébriles</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Rapport bénéfice/risque et information des parents :</strong> le bénéfice — protection <strong>individuelle</strong> et <strong>collective</strong> (immunité de groupe) — dépasse très largement le risque d'effets indésirables graves, qui restent <span class=\"kw-alerte\">exceptionnels</span>. L'information claire et la réassurance des parents font partie intégrante de l'acte vaccinal.</div>\n      <div class=\"callout callout-danger\"><strong>Liens de causalité réfutés — à <span class=\"kw-ci\">ne jamais</span> attribuer à la <span class=\"kw-ttt\">vaccination</span> :</strong> <span class=\"kw-ttt\">hépatite B</span> ou <span class=\"kw-etio\">HPV</span> et <span class=\"kw-ttt\">sclérose</span> en plaques ; <span class=\"kw-ttt\">ROR</span> et autisme ; aluminium et myofasciite à macrophages ; coqueluche et <span class=\"kw-alerte\">mort subite</span> du nourrisson.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 366 — Exposition accidentelle aux liquides biologiques</em></p>","frequence":1},{"id":"146-4","rang":"A","rubrique":"Définition","titre":"Populations et vaccinations : différencier population générale, population à risque et population plus particulièrement exposée","contenu":"<p>Trois catégories de population doivent être distinguées : elles ne relèvent pas des mêmes <span class=\"kw-def\">recommandations vaccinales</span>.</p>\n      <table >\n        <thead><tr><th>Population</th><th>Définition</th><th>Exemples</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Population générale</span></td><td>Relève du <span class=\"kw-def\">calendrier vaccinal</span> standard, par tranche d'âge</td><td>Ensemble de la population</td></tr>\n          <tr><td><span class=\"kw-def\">Population à risque</span></td><td>Risque de <strong>forme grave</strong> de la maladie</td><td><span class=\"kw-ci\">Immunodéprimés</span> ; <span class=\"kw-clinique\">comorbidités</span> ; <span class=\"kw-clinique\">âges extrêmes</span> ; <span class=\"kw-clinique\">femme enceinte</span></td></tr>\n          <tr><td><span class=\"kw-def\">Population particulièrement exposée</span></td><td>Risque <strong>d'exposition</strong> au pathogène</td><td><span class=\"kw-clinique\">Professionnels</span> (santé et autres) ; <span class=\"kw-clinique\">voyageurs</span> ; entourage de sujets fragiles (<span class=\"kw-def\">cocooning</span>) ; <span class=\"kw-clinique\">cas contacts</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Distinction clé :</strong> ne pas confondre le <strong>risque de gravité</strong> (population à risque) et le <strong>risque d'exposition</strong> (population particulièrement exposée).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 175 — Voyage en pays tropical · 174 — Pathologie infectieuse du migrant · 169 — <span class=\"kw-etio\">VIH</span></em></p>","frequence":0},{"id":"146-5","rang":"B","rubrique":"Prise en charge","titre":"Rattrapage vaccinal chez l'enfant et l'adulte : connaître les modalités de rattrapage vaccinal selon les recommandations nationales en vigueur","contenu":"<h4 style=\"margin:4px 0 6px;font-size:14.5px;font-weight:700;\">Principes du rattrapage</h4>\n      <ul>\n        <li>Protéger en priorité contre <span class=\"kw-clinique\">les</span> infections les plus sévères.</li>\n        <li>Réduire le nombre d'injections en utilisant <span class=\"kw-clinique\">les</span> vaccins combinés disponibles.</li>\n        <li>Respecter la tolérance — rarement <span class=\"kw-chiffre\">&gt; 2 injections</span> le même jour.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Règle de base :</strong> chaque dose déjà reçue <strong>compte</strong> — on <strong>complète</strong> le calendrier, on ne le <strong>recommence jamais à zéro</strong>.</div>\n      <p>En cas de <strong>statut vaccinal inconnu ou incertain</strong> : reprise d'un schéma complet adapté à l'âge (aucun risque à sur-vacciner un sujet éventuellement déjà immun). Pour la <span class=\"kw-ttt\">diphtérie-tétanos</span> et l'<span class=\"kw-ttt\">hépatite B</span>, on peut s'aider du <span class=\"kw-bio\">dosage des anticorps</span> après une première injection.</p>\n      <div class=\"callout callout-warn\"><strong>Urgences de protection :</strong> <span class=\"kw-ttt\">coqueluche</span> <span class=\"kw-chiffre\">&lt; 6 mois</span> ; germes encapsulés (<span class=\"kw-ttt\">pneumocoque</span>, <span class=\"kw-ttt\">Hib</span>, <span class=\"kw-ttt\">méningocoque</span>) <span class=\"kw-chiffre\">&lt; 2 ans</span> ; <span class=\"kw-ttt\">hépatite B</span>, <span class=\"kw-ttt\">HPV</span> et <span class=\"kw-ttt\">coqueluche</span> à l'adolescence ; <span class=\"kw-ttt\">rougeole</span> <strong>à tout âge</strong>.</div>\n      <h4 style=\"margin:16px 0 6px;font-size:14.5px;font-weight:700;\">Rattrapage des non-vaccinés</h4>\n      <table >\n        <thead><tr><th>Vaccin</th><th>Modalités de rattrapage</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\">ROR</span></td><td>2 doses à<span class=\"kw-chiffre\"> 1 mois</span> d'intervalle pour <span class=\"kw-clinique\">les</span> sujets nés depuis 1980 (<span class=\"kw-chiffre\">≤ 43 ans</span>)</td></tr>\n          <tr><td><span class=\"kw-ttt\">Méningocoque C</span></td><td>1 dose unique jusqu'à <span class=\"kw-chiffre\">24 ans</span> révolus</td></tr>\n          <tr><td><span class=\"kw-ttt\">Hépatite B</span></td><td>Schéma complet jusqu'à <span class=\"kw-chiffre\">15 ans</span> révolus</td></tr>\n          <tr><td><span class=\"kw-ttt\">HPV</span></td><td><span class=\"kw-chiffre\">15-19 ans</span> : 3 doses (<span class=\"kw-chiffre\">M0, M2, M6</span>) ; HSH jusqu'à <span class=\"kw-chiffre\">26 ans</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Coqueluche</span></td><td>Rappel jusqu'à <span class=\"kw-chiffre\">39 ans</span> si le rappel de <span class=\"kw-chiffre\">25 ans</span> n'a pas été reçu</td></tr>\n        </tbody>\n      </table>","frequence":2},{"id":"146-6","rang":"A","rubrique":"Prise en charge","titre":"Connaître le calendrier des vaccinations (obligatoires et recommandées) en vigueur en France dans la population générale (diphtérie, tétanos, poliomyélite, coqueluche, infection invasive à Haemophilus influenzae de type b, hépatite B, rougeole, oreillons, rubéole, infection invasive à méningocoque, infection à pneumocoque, infection à HPV, grippe saisonnière)","contenu":"<p>Pour <span class=\"kw-clinique\">les</span> enfants nés depuis <span class=\"kw-chiffre\">2018</span>, <strong>11 vaccinations sont obl<span class=\"kw-chiffre\">iga</span>toires</strong> : <span class=\"kw-ttt\">diphtérie</span>, <span class=\"kw-ttt\">tétanos</span>, <span class=\"kw-ttt\">poliomyélite</span>, <span class=\"kw-ttt\">coqueluche</span>, <span class=\"kw-ttt\">Haemophilus influenzae b</span>, <span class=\"kw-ttt\">pneumocoque (VPC13)</span>, <span class=\"kw-ttt\">méningocoque C</span>, <span class=\"kw-ttt\">rougeole</span>, <span class=\"kw-ttt\">oreillons</span>, <span class=\"kw-ttt\">rubéole</span>, <span class=\"kw-ttt\">hépatite B</span>.</p>\n      <div class=\"callout callout-info\"><strong>Formes combinées :</strong> hexavalent <span class=\"kw-ttt\">DTCaP-Hib-HB</span> ; pentavalent <span class=\"kw-ttt\">DTCaP-Hib</span> ; tétravalent <span class=\"kw-ttt\">DTCaP</span> ou <span class=\"kw-ttt\">dTcaP</span>.</div>\n      <h4 style=\"margin:16px 0 6px;font-size:14.5px;font-weight:700;\">Calendrier du nourrisson et de l'enfant</h4>\n      <table >\n        <thead><tr><th>Vaccin</th><th>Primovaccination</th><th>Rappels</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\">DTCaP-Hib-HB</span></td><td><span class=\"kw-chiffre\">M2</span>, <span class=\"kw-chiffre\">M4</span></td><td><span class=\"kw-chiffre\">M11</span>, puis <span class=\"kw-chiffre\">6 ans</span> et <span class=\"kw-chiffre\">11-13 ans</span> (<span class=\"kw-ttt\">DTCaP</span>)</td></tr>\n          <tr><td><span class=\"kw-ttt\">Pneumocoque VPC13</span></td><td><span class=\"kw-chiffre\">M2</span>, <span class=\"kw-chiffre\">M4</span></td><td><span class=\"kw-chiffre\">M11</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Méningocoque C</span></td><td><span class=\"kw-chiffre\">M5</span></td><td><span class=\"kw-chiffre\">M12</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Méningocoque B</span> <em>(recommandé)</em></td><td><span class=\"kw-chiffre\">M3</span>, <span class=\"kw-chiffre\">M5</span></td><td><span class=\"kw-chiffre\">M12</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">ROR</span></td><td><span class=\"kw-chiffre\">M12</span></td><td><span class=\"kw-chiffre\">M16-18</span></td></tr>\n        </tbody>\n      </table>\n      <p>L'intervalle de primovaccination est de <span class=\"kw-chiffre\">2 mois</span> (depuis le passage au schéma à 2 doses en 2013) ; le 1er rappel a lieu <span class=\"kw-chiffre\">≥ 6 mois</span> plus tard.</p>\n      <h4 style=\"margin:16px 0 6px;font-size:14.5px;font-weight:700;\"><span class=\"kw-ttt\">Vaccination</span> <span class=\"kw-etio\">HPV</span> (papillomavirus)</h4>\n      <table >\n        <thead><tr><th>Population</th><th>Schéma</th></tr></thead>\n        <tbody>\n          <tr><td>Population générale <span class=\"kw-chiffre\">11-14 ans</span> — filles <strong>et</strong> garçons</td><td>2 doses espacées de <span class=\"kw-chiffre\">6 à 13 mois</span> : <span class=\"kw-chiffre\">M0</span>, <span class=\"kw-chiffre\">M6</span></td></tr>\n          <tr><td>Rattrapage <span class=\"kw-chiffre\">15-19 ans</span></td><td>3 doses : <span class=\"kw-chiffre\">M0</span>, <span class=\"kw-chiffre\">M2</span>, <span class=\"kw-chiffre\">M6</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">HSH</span> jusqu'à <span class=\"kw-chiffre\">26 ans</span></td><td>3 doses : <span class=\"kw-chiffre\">M0</span>, <span class=\"kw-chiffre\">M2</span>, <span class=\"kw-chiffre\">M6</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Vaccin <span class=\"kw-etio\">HPV</span> :</strong> <span class=\"kw-ttt\">nonavalent (Gardasil 9)</span> — couvre <span class=\"kw-clinique\">les</span> génotypes <span class=\"kw-chiffre\">6, 11, 16, 18, 31, 33, 45, 52, 58</span>. Les types <span class=\"kw-chiffre\">6</span> et <span class=\"kw-chiffre\">11</span> (non oncogènes) sont responsables d'environ <span class=\"kw-chiffre\">90 %</span> des <span class=\"kw-clinique\">condylomes</span> ; l'efficacité est d'autant plus grande que la <span class=\"kw-ttt\">vaccination</span> précède le début de l'activité sexuelle.</div>\n      <h4 style=\"margin:16px 0 6px;font-size:14.5px;font-weight:700;\">Calendrier de l'adulte</h4>\n      <table >\n        <thead><tr><th>Âge</th><th>Vaccinations</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-chiffre\">25 ans</span></td><td><span class=\"kw-ttt\">dTcaP</span></td></tr>\n          <tr><td><span class=\"kw-chiffre\">45 ans</span></td><td><span class=\"kw-ttt\">dTP</span></td></tr>\n          <tr><td><span class=\"kw-chiffre\">65 ans</span></td><td><span class=\"kw-ttt\">dTP</span> + <span class=\"kw-ttt\">grippe</span> annuelle + <span class=\"kw-ttt\">zona</span> (Shingrix, recommandé entre <span class=\"kw-chiffre\">65-74 ans</span>)</td></tr>\n          <tr><td><span class=\"kw-chiffre\">≥ 75 ans</span></td><td><span class=\"kw-ttt\">dTP</span> tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">10 ans</span></td></tr>\n        </tbody>\n      </table>\n      <p>Le <span class=\"kw-ttt\">COVID-19</span> est recommandé dès <span class=\"kw-chiffre\">5 ans</span> en population générale et obl<span class=\"kw-chiffre\">iga</span>toire chez <span class=\"kw-clinique\">les</span> professionnels de santé et du social.</p>\n      <div class=\"callout callout-warn\"><strong>Piège :</strong> le <span class=\"kw-ttt\">ROR</span> et l'obl<span class=\"kw-chiffre\">iga</span>tion 2018 concernent <span class=\"kw-clinique\">les</span> <strong>nourrissons</strong>, <strong>pas</strong> les femmes en âge de procréer. Une couverture vaccinale <span class=\"kw-chiffre\">&gt; 95 %</span> est nécessaire pour bloquer la circulation de la rougeole.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 160 — Tétanos · 163 — Coqueluche · 167 — Hépatites virales · 151 — <span class=\"kw-clinique\">Méningite</span> - méningoencéphalite · 300 — Tumeur col-corps utérin</em></p>","frequence":7},{"id":"146-7","rang":"A","rubrique":"Prise en charge","titre":"Connaître le calendrier des vaccinations (obligatoires et recommandées) en vigueur en France dans les populations particulières (adultes et enfants) : personnes âgées de 65 ans ou plus (diphtérie, tétanos, poliomyélite, grippe saisonnière, infection à pneumocoque, zona, coqueluche) ; femme enceinte ; professionnels de santé","contenu":"<h4 style=\"margin:4px 0 6px;font-size:14.5px;font-weight:700;\">Personnes âgées de <span class=\"kw-chiffre\">65 ans</span> et plus</h4>\n      <table >\n        <thead><tr><th>Vaccin</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\">dTP</span></td><td>Rappel tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">10 ans</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Grippe</span></td><td>1 dose annuelle</td></tr>\n          <tr><td><span class=\"kw-ttt\">Pneumocoque</span></td><td>HAS 2024 : <span class=\"kw-ttt\">Prevenar-20</span> élargi à <strong>toutes</strong> <span class=\"kw-clinique\">les</span> personnes <span class=\"kw-chiffre\">≥ 65 ans</span> (plus seulement les comorbides)</td></tr>\n          <tr><td><span class=\"kw-ttt\">Zona</span></td><td><span class=\"kw-ttt\">Shingrix</span>, 2 doses (<span class=\"kw-chiffre\">M0, M2</span>), recommandé dès <span class=\"kw-chiffre\">65 ans</span> même en cas de <span class=\"kw-clinique\">zona</span> ou de Zostavax antérieur</td></tr>\n          <tr><td><span class=\"kw-ttt\">Coqueluche</span></td><td>À l'occasion du rappel dTP</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:16px 0 6px;font-size:14.5px;font-weight:700;\">Femme enceinte</h4>\n      <table >\n        <thead><tr><th>Vaccin</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\">Grippe</span> injectable</td><td>Recommandée <strong>quel que soit le trimestre</strong> de la <span class=\"kw-ci\">grossesse</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Coqueluche</span></td><td>À partir du <span class=\"kw-chiffre\">2e trimestre</span> (idéalement <span class=\"kw-chiffre\">20-36 SA</span>) — favorise le transfert transplacentaire des AC maternels</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-ci\">Contre-indication</span> absolue chez la femme enceinte :</strong> <span class=\"kw-clinique\">les</span> vaccins vivants — <span class=\"kw-ttt\">ROR</span>, <span class=\"kw-ttt\">varicelle</span>, <span class=\"kw-ttt\">BCG</span>.</div>\n      <h4 style=\"margin:16px 0 6px;font-size:14.5px;font-weight:700;\">Professionnels de santé</h4>\n      <table >\n        <thead><tr><th>Statut</th><th>Vaccins</th></tr></thead>\n        <tbody>\n          <tr><td>Obl<span class=\"kw-chiffre\">iga</span>toires</td><td><span class=\"kw-ttt\">DTP</span> ; <span class=\"kw-ttt\">hépatite B</span> ; <span class=\"kw-ttt\">COVID-19</span> ; <span class=\"kw-ttt\">typhoïde</span> pour le personnel de laboratoire manipulant des selles</td></tr>\n          <tr><td>Recommandés</td><td><span class=\"kw-ttt\">ROR</span> (2 doses si né après 1980) ; <span class=\"kw-ttt\">grippe</span> ; <span class=\"kw-ttt\">coqueluche</span> (au rappel dTP) ; <span class=\"kw-ttt\">varicelle</span> si non immunisé</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>BCG :</strong> n'est plus obl<span class=\"kw-chiffre\">iga</span>toire pour <span class=\"kw-clinique\">les</span> professionnels de santé depuis 2019.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 163 — Coqueluche</em></p>","frequence":4},{"id":"146-8","rang":"B","rubrique":"Prise en charge","titre":"Appliquer le calendrier des vaccinations (obligatoires et recommandées) en vigueur en France dans les populations particulières : prématurés et immunodéprimés et aspléniques, professionnels, hors professionnels de santé","contenu":"<h4 style=\"margin:4px 0 6px;font-size:14.5px;font-weight:700;\">Nourrisson né prématuré</h4>\n      <p><span class=\"kw-ttt\">Vaccination</span> de routine dès <span class=\"kw-chiffre\">2 mois</span> d'âge chronologique, quel que soit le degré de prématurité. Mêmes schémas qu'à terme <strong>sauf pour le <span class=\"kw-etio\">pneumocoque</span></strong> : primovaccination renforcée à <span class=\"kw-chiffre\">2-3-4 mois</span> puis rappel à <span class=\"kw-chiffre\">11 mois</span> (schéma 3+1 doses de <span class=\"kw-ttt\">VPC13</span>).</p>\n      <h4 style=\"margin:16px 0 6px;font-size:14.5px;font-weight:700;\">Immunodéprimé et asplénique</h4>\n      <div class=\"callout callout-warn\"><strong>Principe :</strong> efficacité vaccinale diminuée → contrôle par <span class=\"kw-bio\">dosages d'anticorps post-vaccinaux</span>. <span class=\"kw-clinique\">Les</span> vaccins <span class=\"kw-ci\">vivants sont contre-indiqués</span> (sauf exceptions évaluées au cas par cas).</div>\n      <p>Socle commun : mise à jour du calendrier + <span class=\"kw-ttt\">grippe</span> + <span class=\"kw-ttt\">pneumocoque</span> + <span class=\"kw-ttt\">COVID-19</span> + <span class=\"kw-ttt\">méningocoque ACYW et B</span> + <span class=\"kw-ttt\">HPV</span>.</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Schéma spécifique</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Splénectomie / asplénie</span></td><td>Prophylaxie <span class=\"kw-chiffre\">≥ 2 semaines avant</span> (ou <span class=\"kw-chiffre\">2 semaines</span> après si <span class=\"kw-alerte\">urgence</span>) ; <span class=\"kw-ttt\">pneumocoque</span> VPC13 puis VPP23 à<span class=\"kw-chiffre\"> 2 mois</span> puis VPP23 tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">5 ans</span> ; <span class=\"kw-ttt\">grippe</span> annuelle ; <span class=\"kw-ttt\">Hib</span> 1 dose ; <span class=\"kw-ttt\">méningocoque ACYW</span> (2 injections à<span class=\"kw-chiffre\"> 6 mois</span>, rappel /<span class=\"kw-chiffre\">5 ans</span>) et <span class=\"kw-ttt\">B</span> (2 injections à<span class=\"kw-chiffre\"> 1 mois</span>)</td></tr>\n          <tr><td><span class=\"kw-def\">Greffe d'organe solide</span></td><td>Vaccins vivants <span class=\"kw-ci\">définitivement contre-indiqués</span> ; autres vaccins à intervalles rapprochés</td></tr>\n          <tr><td><span class=\"kw-def\">Allogreffe de CSH</span></td><td>Reprise du <span class=\"kw-ttt\">calendrier vaccinal</span> à zéro (comme un nourrisson)</td></tr>\n          <tr><td><span class=\"kw-etio\">VIH</span></td><td>Vaccins vivants possibles si <span class=\"kw-chiffre\">CD4 &gt; 200/mm³</span> et charge <span class=\"kw-etio\">virale</span> indétectable ; systématiques : DT-polio (/<span class=\"kw-chiffre\">10 ans</span> dès <span class=\"kw-chiffre\">25 ans</span>), <span class=\"kw-etio\">pneumocoque</span>, <span class=\"kw-etio\">grippe</span>, <span class=\"kw-ttt\">hépatite B</span> ; selon contexte : <span class=\"kw-clinique\">fièvre</span> jaune (si <span class=\"kw-chiffre\">CD4</span> &gt; 200 et &gt;<span class=\"kw-chiffre\"> 15 %</span>), <span class=\"kw-etio\">HPV</span>, hépatite A</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-etio\">VIH</span> :</strong> le <span class=\"kw-ci\">BCG est contre-indiqué dans tous les cas</span>, quel que soit le taux de <span class=\"kw-chiffre\">CD4</span>.</div>\n      <h4 style=\"margin:16px 0 6px;font-size:14.5px;font-weight:700;\">Professionnels hors santé</h4>\n      <table >\n        <thead><tr><th>Vaccin</th><th>Métiers concernés</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\">Grippe</span></td><td><span class=\"kw-def\">Contact</span> régulier avec des sujets à risque ; personnels nav<span class=\"kw-chiffre\">iga</span>nts</td></tr>\n          <tr><td><span class=\"kw-ttt\">Rage</span></td><td>Vétérinaires ; personnels de laboratoires</td></tr>\n          <tr><td><span class=\"kw-ttt\">Hépatite A</span></td><td>Petite enfance ; traitement des eaux usées ; restauration collective</td></tr>\n          <tr><td><span class=\"kw-ttt\">Hépatite B</span></td><td>Thanatopracteurs (<strong>obl<span class=\"kw-chiffre\">iga</span>toire</strong>) ; tatoueurs ; éboueurs</td></tr>\n          <tr><td><span class=\"kw-ttt\">ROR</span> et <span class=\"kw-ttt\">coqueluche</span></td><td>Personnes au <span class=\"kw-def\">contact</span> d'enfants ; assistantes maternelles</td></tr>\n          <tr><td><span class=\"kw-ttt\">Varicelle</span></td><td>Personnels de la petite enfance non immunisés</td></tr>\n          <tr><td><span class=\"kw-ttt\">Leptospirose</span></td><td>Égoutiers ; personnel agricole exposé</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 169 — <span class=\"kw-etio\">VIH</span> · 159 — <span class=\"kw-etio\">Tuberculose</span> Enfant / Adulte</em></p>","frequence":4},{"id":"146-9","rang":"A","rubrique":"Prise en charge","titre":"Vacciner en pratique courante : connaître les modalités de contrôle de la douleur liée à l'injection vaccinale ; connaître les modalités de notification qu'une vaccination a bien été effectuée ; connaître l'intérêt du carnet de vaccination électronique","contenu":"<h4 style=\"margin:4px 0 6px;font-size:14.5px;font-weight:700;\">Contrôle de la douleur liée à l'injection</h4>\n      <p><strong>Technique d'injection :</strong> ne pas purger la seringue de son <span class=\"kw-def\">air</span>, obtenir un <span class=\"kw-clinique\">relâchement musculaire</span>, utiliser une <span class=\"kw-clinique\">aiguille de longueur adaptée à l'âge</span>, injecter <span class=\"kw-clinique\">rapidement en une seule fois</span> sans aspiration préalable.</p>\n      <p><strong>Analgésie selon l'âge :</strong></p>\n      <ul>\n        <li>Distraction de l'enfant — à tout âge.</li>\n        <li>Nourrisson : pendant la <span class=\"kw-clinique\">tétée</span> ou après quelques gouttes de <span class=\"kw-ttt\">saccharose 24 %</span>.</li>\n        <li>Position <strong>assis ou porté, pas couché</strong> ; environnement rassurant.</li>\n        <li>Crème <span class=\"kw-ttt\">EMLA</span> en patch <span class=\"kw-chiffre\">1 h</span> avant — n'agit que sur la douleur de la traversée cutanée, pas sur celle liée au produit.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Vaccins <span class=\"kw-clinique\">les</span> plus douloureux :</strong> <span class=\"kw-ttt\">pneumocoque</span> et <span class=\"kw-ttt\">HPV</span>, puis <span class=\"kw-ttt\">hépatite</span> et <span class=\"kw-ttt\">rougeole</span>.</div>\n      <h4 style=\"margin:16px 0 6px;font-size:14.5px;font-weight:700;\">Notification de la <span class=\"kw-ttt\">vaccination</span></h4>\n      <p>Le patient reçoit une <span class=\"kw-def\">attestation écrite</span> portée sur le carnet de santé, le carnet de <span class=\"kw-ttt\">vaccination</span> ou le <span class=\"kw-def\">carnet de vaccination électronique</span> national, mentionnant la <span class=\"kw-chiffre\">date</span>, le <span class=\"kw-def\">nom du vaccin</span> et le <span class=\"kw-def\">numéro de lot</span>.</p>\n      <h4 style=\"margin:16px 0 6px;font-size:14.5px;font-weight:700;\">Carnet de <span class=\"kw-ttt\">vaccination</span> électronique</h4>\n      <p>Outil national de <span class=\"kw-def\">traçabilité</span> et de mise à jour du <span class=\"kw-def\">statut vaccinal</span>, accessible au patient comme au professionnel de santé.</p>","frequence":0}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"liensGlobaux":[{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-146.pdf","label":"Collège Pilly — Vaccinations (item 146, PDF 2023)"}],"cards":[]};